import {LANGS,translator,localized} from './i18n.js';
import {DESTINATIONS,BY_ID,ARTICLE_IMAGES,ERA_LABELS,DISHES,RESTAURANTS,PRACTICAL,L} from './content.js';
import {DEFAULT_PLAN,COST_PRESETS,CURRENCIES,normalizePlan,createJourney,addDays,calendarFile} from './journey.js';

const $=s=>document.querySelector(s),$$=s=>Array.from(document.querySelectorAll(s));
const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cut=(s,n=150)=>s.length<=n?s:s.slice(0,n).replace(/\s+\S*$/,'')+'…';
const readStore=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}};
const writeStore=(key,v)=>{try{localStorage.setItem(key,JSON.stringify(v));return true;}catch{return false;}};
let lang=readStore('biladi-lang','fr');if(!LANGS.some(l=>l.id===lang))lang='fr';
let t=translator(lang);const loc=v=>localized(v,lang);
const state={wilayas:[],photos:[],editorial:{articles:[],supporting_articles:[],culture_profiles:[],people:[],companies:[],source_registry:{}},summary:{},svg:'',mapPaths:[],favourites:new Set((Array.isArray(readStore('biladi-favourites',[]))?readStore('biladi-favourites',[]):[]).filter(x=>typeof x==='string')),savedTrip:readStore('biladi-trip',null),hero:0,destFilter:'all',storyFilter:'all',selectedWilaya:'06',directory:[],directoryLoaded:false,directoryPromise:null,directoryFilter:'all',directoryQuery:'',directoryWilaya:'all',directoryLimit:30,searchQuery:'',plan:null,journey:null};
let renderVersion=0,toastTimer,searchTimer;
const iconPaths={arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4.5 4.5"/>',menu:'<path d="M4 7h16M4 12h16M4 17h16"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',bookmark:'<path d="M6 3h12v18l-6-4-6 4Z"/>',book:'<path d="M12 5c-3-2-6-2-10-1v15c4-1 7-1 10 1m0-15c3-2 6-2 10-1v15c-4-1-7-1-10 1V5Z"/>',plane:'<path d="m22 2-7 20-4-9-9-4 20-7Zm-11 11 11-11"/>',compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-2.5 5.5L8 16l2.5-5.5L16 8Z"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v2m0 18v2M1 12h2m18 0h2M4.2 4.2l1.4 1.4m12.8 12.8 1.4 1.4m0-15.6-1.4 1.4M5.6 18.4l-1.4 1.4"/>',passport:'<rect x="5" y="2" width="14" height="20" rx="2"/><circle cx="12" cy="10" r="4"/><path d="M8 10h8M12 6c-2 2-2 6 0 8 2-2 2-6 0-8Zm-3 12h6"/>',wallet:'<path d="M20 6H5a2 2 0 0 1 0-4h13v4m2 0v15H4a2 2 0 0 1-2-2V4m18 6h-6v6h6"/><path d="M16 13h.1"/>',camera:'<path d="M3 6h4l2-3h6l2 3h4v15H3Z"/><circle cx="12" cy="13" r="4"/>',shield:'<path d="m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6l9-4Z"/><path d="m8 12 3 3 5-6"/>',accessibility:'<circle cx="12" cy="4" r="2"/><path d="M4 8h16m-8 0v7m0 0-5 7m5-7 5 7"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',car:'<path d="m5 5-2 7v6h18v-6l-2-7H5Zm-2 7h18M5 18v3m14-3v3M6 15h.1M18 15h.1"/>',globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c-6 5-6 13 0 18 6-5 6-13 0-18Z"/>',check:'<path d="m5 12 4 4L20 5"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>'};
function icon(name){return `<svg class="icon ${name==='arrow'?'arrow':''}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[name]||iconPaths.compass}</svg>`;}
function brand(){return `<a class="brand" href="#home" aria-label="BILADI — El Djazaïr"><img class="brand-icon" src="./assets/logo.svg" width="39" height="40" alt=""><span><span class="brand-name" dir="ltr">BILADI</span><span class="brand-sub" dir="ltr">EL DJAZAÏR · الجزائر</span></span></a>`;}
function img(id,cls='',eager=false){const p=state.photos.find(p=>p.id===id);if(!p)return '';return `<img src="./assets/${h(p.filename)}" alt="${h(loc(p.alt)||p.label)}" class="${h(cls)}" width="${p.dimensions[0]}" height="${p.dimensions[1]}" loading="${eager?'eager':'lazy'}" ${eager?'fetchpriority="high"':''} decoding="async">`;}
function photoLabel(id){return state.photos.find(p=>p.id===id)?.label||'';}
function sourceLink(url,label){try{const u=new URL(url);if(!['http:','https:'].includes(u.protocol))return '';return `<a href="${h(u.href)}" target="_blank" rel="noopener noreferrer">${h(label||t('source'))} ${icon('arrow')}</a>`;}catch{return '';}}
function photoCredit(id){return `<button class="photo-credit" data-action="photo-credit" data-id="${h(id)}">${h(t('photoCredit'))} · ${h(state.photos.find(p=>p.id===id)?.photographer||'')}</button>`;}
function saveButton(key,extra=''){const active=state.favourites.has(key);return `<button class="icon-btn save-btn ${active?'active':''} ${extra}" data-action="favourite" data-key="${h(key)}" aria-pressed="${active}" aria-label="${h(active?t('saved'):t('save'))}">${icon('bookmark')}</button>`;}
function destinationCard(d,large=false){return `<article class="destination-card ${large?'large':''}">${d.photo?img(d.photo):`<div class="story-image-placeholder" aria-hidden="true">${h(loc(d.name).slice(0,1))}</div>`}<a class="cover-link" href="#destination/${d.id}" aria-label="${h(loc(d.name))}"></a>${saveButton('destination:'+d.id)}<span class="card-region">${h(t(d.theme))}</span><h3>${h(loc(d.name))}</h3><p>${h(cut(loc(d.lead),large?160:100))}</p><span class="card-link">${h(t('viewDestination'))}${icon('arrow')}</span></article>`;}
function allArticles(){return [...state.editorial.articles,...state.editorial.supporting_articles];}
function articleImage(a){if(a.id==='cleopatra-juba-cherchell')return state.photos.some(p=>p.id==='cherchell')?'cherchell':ARTICLE_IMAGES[a.id];return ARTICLE_IMAGES[a.id]||'algiers';}
function articleCard(a){const p=articleImage(a);return `<article class="story-card">${img(p)}${saveButton('article:'+a.id)}<div class="story-text"><span class="tag">${h(loc(ERA_LABELS[a.era])||t(a.category))}</span><h3>${h(loc(a.title))}</h3><p>${h(cut(loc(a.body),180))}</p><a class="text-link" href="#article/${h(a.id)}">${h(t('readStory'))}${icon('arrow')}</a></div></article>`;}
function dateLabel(iso){return new Intl.DateTimeFormat(lang==='ar'?'ar-DZ':lang==='zh'?'zh-CN':lang,{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(iso+'T12:00:00Z'));}
function money(v,plan=state.plan){return new Intl.NumberFormat(lang==='ar'?'ar-DZ':lang==='zh'?'zh-CN':lang,{style:'currency',currency:plan.currency,maximumFractionDigits:0}).format(v);}
function province(code){return state.wilayas.find(w=>String(w.code).padStart(2,'0')===String(code).padStart(2,'0'));}
function provinceName(w){return w?(lang==='ar'?w.name_ar:w.name_fr):'';}
function provincePhoto(code){const curated=DESTINATIONS.find(d=>d.wilaya===code&&d.photo);return state.photos.some(p=>p.id==='wilaya-'+code)?'wilaya-'+code:curated?.photo;}
function sourceList(sources){return `<div class="source-links">${(sources||[]).map(s=>sourceLink(s.url,`${s.publisher||s.title} — ${s.title}`)).join('')}</div>`;}

function renderHeader(route){
 const names=[['destinations','discover'],['atlas','atlas'],['history','history'],['culture','culture'],['food','food']];
 $('#header').innerHTML=`<div class="header-inner">${brand()}<nav class="nav-links" aria-label="Navigation">${names.map(([r,k])=>`<a href="#${r}" class="${route===r?'current':''}">${h(t(k))}</a>`).join('')}</nav><div class="header-actions"><button class="icon-btn" data-action="search" aria-label="${h(t('search'))}">${icon('search')}</button><a class="icon-btn" href="#notebook" aria-label="${h(t('notebook'))}">${icon('bookmark')}</a><label><span class="visually-hidden" style="position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)">Language</span><select class="lang-picker" aria-label="Language / Langue / اللغة">${LANGS.map(l=>`<option value="${l.id}" ${l.id===lang?'selected':''}>${l.label} · ${l.name}</option>`).join('')}</select></label><a class="header-cta" href="#planner">${h(t('planner'))}</a><button class="mobile-menu-btn" data-action="menu" aria-label="${h(t('menu'))}" aria-expanded="false" aria-controls="mobile-menu">${icon('menu')}</button></div></div><nav id="mobile-menu" class="mobile-menu" aria-label="Mobile navigation">${names.map(([r,k])=>`<a href="#${r}">${h(t(k))}</a>`).join('')}<a href="#practical">${h(t('practical'))}</a><a href="#notebook">${h(t('notebook'))}</a><a class="btn btn-primary" href="#planner">${h(t('planner'))}${icon('arrow')}</a></nav>`;
 $('#footer').innerHTML=`<div class="container"><div class="footer-top"><div class="footer-brand">${brand()}<p class="footer-tagline">${h(t('footerLine'))}</p><div class="footer-arabic" lang="ar">بلادي، الجزائر</div></div><div class="footer-links"><h3>${h(t('explore'))}</h3>${names.map(([r,k])=>`<a href="#${r}">${h(t(k))}</a>`).join('')}</div><div class="footer-links"><h3>${h(t('travelNotice'))}</h3><a href="#planner">${h(t('planner'))}</a><a href="#practical">${h(t('practical'))}</a><a href="#notebook">${h(t('notebook'))}</a><a href="#directory">${h(t('directory'))}</a><a href="#sources">${h(t('sources'))}</a></div></div><div class="footer-bottom"><p>${h(t('notOfficial'))}<br>${h(t('localOnly'))}</p><p class="copyright">© 2026 BILADI · ${h(t('copyright'))}<br>© OpenStreetMap contributors · ODbL</p></div></div>`;
}

const HEROES=[{photo:'djanet',place:'Tadrart Rouge · Djanet'},{photo:'bejaia',place:'Cap Carbon · Béjaïa'},{photo:'constantine-sunset',place:'Gorges du Rhumel · Constantine'}];
function heroMarkup(){const slide=HEROES[state.hero];return `<section class="hero">${img(slide.photo,'hero-photo',true)}<div class="hero-content container"><span class="eyebrow">${h(t('heroEyebrow'))}</span><h1>${h(t('heroA'))}<br><em>${h(t('heroB'))}</em></h1><p class="hero-description">${h(t('heroDesc'))}</p><div class="button-row"><a class="btn btn-cream" href="#atlas">${h(t('explore'))}${icon('arrow')}</a><a class="btn btn-ghost" href="#planner">${h(t('planner'))}${icon('compass')}</a></div></div><button class="hero-scroll" data-action="scroll-discover">${h(t('scroll'))}</button><div class="hero-bottom container"><div><span class="hero-location">${icon('pin')}<span dir="auto">${h(slide.place)}</span></span><button class="hero-credit" data-action="photo-credit" data-id="${slide.photo}">${h(state.photos.find(p=>p.id===slide.photo)?.attribution||'')}</button></div><div class="hero-steps">${HEROES.map((s,i)=>`<button class="hero-step ${state.hero===i?'active':''}" data-action="hero" data-index="${i}" aria-pressed="${state.hero===i}"><strong>0${i+1}</strong>${h(s.place.split(' · ')[1])}</button>`).join('')}</div></div></section>`;}
function atlasMarkup(full=false){const w=province(state.selectedWilaya),sum=state.summary[state.selectedWilaya]||{},p=provincePhoto(state.selectedWilaya);return `<section class="atlas-section section ${full?'atlas-page':''}"><div class="container"><span class="eyebrow">${h(t('atlasEyebrow'))}</span><h${full?'1':'2'} class="section-title">${h(t('atlasTitle'))}</h${full?'1':'2'}><p class="section-desc">${h(t('atlasDesc'))}</p><div class="atlas-layout"><div class="atlas-map"><span class="sea-label">${h(loc(L('Mer Méditerranée','Mediterranean Sea','البحر المتوسط','Mittelmeer','Mar Mediterraneo','Mar Mediterráneo','Mar Mediterrâneo','地中海')))}</span>${state.svg}<span class="border-label border-morocco">${h(loc(L('Maroc','Morocco','المغرب','Marokko','Marocco','Marruecos','Marrocos','摩洛哥')))}</span><span class="border-label border-ws">${h(loc(L('Sahara occidental','Western Sahara','الصحراء الغربية','Westsahara','Sahara occidentale','Sáhara Occidental','Saara Ocidental','西撒哈拉')))}</span><span class="border-label border-mauritania">${h(loc(L('Mauritanie','Mauritania','موريتانيا','Mauretanien','Mauritania','Mauritania','Mauritânia','毛里塔尼亚')))}</span><span class="border-label border-mali">${h(loc(L('Mali','Mali','مالي','Mali','Mali','Mali','Mali','马里')))}</span><span class="border-label border-niger">${h(loc(L('Niger','Niger','النيجر','Niger','Niger','Níger','Níger','尼日尔')))}</span><span class="border-label border-libya">${h(loc(L('Libye','Libya','ليبيا','Libyen','Libia','Libia','Líbia','利比亚')))}</span><span class="border-label border-tunisia">${h(loc(L('Tunisie','Tunisia','تونس','Tunesien','Tunisia','Túnez','Tunísia','突尼斯')))}</span><div class="map-tooltip" id="map-tooltip"></div></div><div class="atlas-panel"><label for="wilaya-select" class="eyebrow">${h(t('chooseWilaya'))}</label><select id="wilaya-select">${state.wilayas.map(v=>`<option value="${String(v.code).padStart(2,'0')}" ${String(v.code).padStart(2,'0')===state.selectedWilaya?'selected':''}>${String(v.code).padStart(2,'0')} · ${h(provinceName(v))}</option>`).join('')}</select><div id="atlas-selected"><span class="tag" style="border-color:#ffffff35;margin-top:25px">${h(t('wilayas'))} ${h(state.selectedWilaya)}</span><h3>${h(provinceName(w))}</h3>${p?img(p,'atlas-preview'):''}<div class="wilaya-count"><div><strong>${Object.values(sum).reduce((a,b)=>a+b,0)}</strong><span>${h(t('directory'))}</span></div><div><strong>${sum.lodging||0}</strong><span>${h(t('lodging'))}</span></div></div><a class="btn btn-gold" href="#wilaya/${state.selectedWilaya}">${h(t('openWilaya'))}${icon('arrow')}</a></div><p class="atlas-note">${h(t('mapNote'))}<br><a href="#sources">${h(t('sources'))} · © Chemseddine Allioua</a></p></div></div></div></section>`;}
function homeView(){
 const ds=['bejaia','djanet','tipasa','constantine','ghardaia'].map(k=>BY_ID[k]);const shown=state.destFilter==='all'?ds:DESTINATIONS.filter(d=>d.theme===state.destFilter).slice(0,5);
 const picks=[state.editorial.articles[0],state.editorial.articles[2],state.editorial.articles[7]].filter(Boolean);
 return `${heroMarkup()}<section class="section"><div class="container"><div class="intro"><div><span class="eyebrow">${h(t('introEyebrow'))}</span><h2 class="section-title">${h(t('introTitle'))}</h2><p class="section-desc">${h(t('introDesc'))}</p></div><div class="intro-stats"><div class="stat"><div class="stat-value">69</div><div class="stat-label">${h(t('wilayas'))}</div></div><div class="stat"><div class="stat-value">7</div><div class="stat-label">${h(t('heritageSites'))}</div></div><div class="stat"><div class="stat-value" dir="ltr">2 381 741</div><div class="stat-label">${h(t('area'))}</div></div></div></div><div class="intro-divider"></div></div></section><section class="section" id="home-discover" style="padding-top:0"><div class="container"><div class="section-head"><div><span class="eyebrow">${h(t('discover'))} · EL DJAZAÏR</span><h2 class="section-title">${h(t('pickTitle'))}</h2><p class="section-desc">${h(t('pickDesc'))}</p></div><a class="text-link" href="#destinations">${h(t('allDestinations'))}${icon('arrow')}</a></div><div class="filter-row">${['all','sea','desert','mountain','antiquity','tradition'].map(k=>`<button class="pill ${state.destFilter===k?'active':''}" data-action="home-filter" data-filter="${k}" aria-pressed="${state.destFilter===k}">${h(t(k))}</button>`).join('')}</div><div class="discover-grid">${shown.map((d,i)=>destinationCard(d,i===0)).join('')}</div></div></section>${atlasMarkup()}<section class="history-section section"><div class="container history-home-layout"><div class="history-photo">${img('tassili-art')}</div><div><span class="eyebrow">${h(t('historyEyebrow'))}</span><h2 class="section-title">${h(t('historyTitle'))}</h2><p class="section-desc">${h(t('historyDesc'))}</p><div class="history-points">${picks.map(a=>`<a class="history-point" href="#article/${a.id}"><span class="era">${h(a.sortYear<0?Math.abs(a.sortYear)+' BCE':a.sortYear)}</span><h3>${h(loc(a.title))}</h3>${icon('arrow')}</a>`).join('')}</div><a class="btn btn-outline" href="#history">${h(t('allStories'))}${icon('arrow')}</a></div></div></section><section class="section"><div class="container food-hero"><div><span class="eyebrow">${h(t('culture'))} · ${h(t('food'))}</span><h2 class="section-title">${h(t('foodTitle'))}</h2><p class="section-desc">${h(t('foodDesc'))}</p><div class="button-row" style="margin-top:30px"><a class="text-link" href="#food">${h(t('food'))}${icon('arrow')}</a><a class="text-link" href="#culture">${h(t('culture'))}${icon('arrow')}</a></div></div>${img('couscous')}</div></section><section class="journey-home">${img('tadrart')}<div class="container"><span class="eyebrow">${h(t('journeyEyebrow'))}</span><h2 class="section-title">${h(t('journeyTitle'))}</h2><p class="section-desc">${h(t('journeyDesc'))}</p><div class="journey-pills"><a class="pill" href="#planner?preset=antiquity">10 ${h(t('days'))} · ${h(t('antiquity'))}</a><a class="pill" href="#planner?preset=sea">14 ${h(t('days'))} · ${h(t('sea'))}</a><a class="pill" href="#planner?preset=grand">20 ${h(t('days'))} · ${h(t('desert'))}</a></div><a class="btn btn-gold" href="#planner">${h(t('planner'))}${icon('arrow')}</a></div></section>`;
}
function atlasView(){return `${atlasMarkup(true)}<section class="section"><div class="container"><div class="section-head"><div><span class="eyebrow">69 ${h(t('wilayas'))}</span><h2 class="section-title">${h(t('searchAll'))}</h2></div><a href="#directory" class="text-link">4 348 ${h(t('directory'))}${icon('arrow')}</a></div><input class="search-input" id="wilaya-search" placeholder="${h(t('chooseWilaya'))}" aria-label="${h(t('chooseWilaya'))}"><div class="all-wilayas" id="all-wilayas">${wilayaLinks(state.wilayas)}</div><div class="data-disclaimer">${h(t('guidanceNote'))}</div></div></section>`;}
function wilayaLinks(ws){return ws.map(w=>`<a class="wilaya-link" href="#wilaya/${String(w.code).padStart(2,'0')}"><span>${String(w.code).padStart(2,'0')}</span>${h(provinceName(w))}</a>`).join('');}
function destinationsView(){const shown=state.destFilter==='all'?DESTINATIONS:DESTINATIONS.filter(d=>d.theme===state.destFilter);return `<section class="page-intro"><div class="container"><span class="eyebrow">${h(t('discover'))}</span><h1>${h(t('pickTitle'))}</h1><p class="section-desc">${h(t('introDesc'))}</p><div class="filter-row">${['all','sea','desert','mountain','antiquity','tradition'].map(k=>`<button class="pill ${state.destFilter===k?'active':''}" data-action="destination-filter" data-filter="${k}">${h(t(k))}</button>`).join('')}</div><div class="destination-gallery">${shown.map(d=>destinationCard(d)).join('')}</div><div class="button-row" style="margin-top:40px"><a class="btn btn-outline" href="#atlas">69 ${h(t('wilayas'))}${icon('arrow')}</a><a class="btn btn-primary" href="#planner">${h(t('planner'))}${icon('compass')}</a></div></div></section>`;}
function destinationView(id){const d=BY_ID[id];if(!d)return notFound();const articles=allArticles().filter(a=>a.places.some(p=>{const k=fold(p);return k.includes(fold(loc(d.name).split(' & ')[0]))||d.highlights.some(q=>fold(q).includes(k));})).slice(0,3);return `<section class="destination-image-hero" style="margin-top:88px;background:var(--pine)">${d.photo?img(d.photo,'',true):''}<div class="container"><a class="text-link" href="#destinations">${h(t('back'))}</a><span class="eyebrow" style="margin-top:28px">${h(t(d.theme))} · ${h(provinceName(province(d.wilaya)))}</span><h1>${h(loc(d.name))}</h1></div>${d.photo?photoCredit(d.photo):''}</section><section class="section"><div class="container"><div class="destination-body"><div><p class="lead">${h(loc(d.lead))}</p><h2 style="font-size:29px;margin-top:38px">${h(t('featured'))}</h2><ul class="highlights">${d.highlights.map((q,i)=>`<li><span>0${i+1}</span>${h(q)}${sourceLink('https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(q+' Algérie'),t('onMap'))}</li>`).join('')}</ul>${sourceLink(d.source,t('extraSources'))}<div class="button-row" style="margin-top:30px"><button class="btn btn-outline" data-action="favourite" data-key="destination:${d.id}">${icon('bookmark')}${h(state.favourites.has('destination:'+d.id)?t('saved'):t('save'))}</button><a class="btn btn-primary" href="#planner?interest=${d.theme}">${h(t('planner'))}${icon('arrow')}</a></div></div><aside class="fact-box"><h3>${h(t('travelNotice'))}</h3><div class="fact-item"><label>${h(t('bestTime'))}</label>${h(t(d.theme==='desert'?'seasonDesert':d.theme==='sea'?'seasonCoast':d.theme==='mountain'?'seasonMountain':'seasonSpring'))}</div><div class="fact-item"><label>${h(t('airports'))}</label><span dir="ltr">${d.airport}</span> · ${h(t('estimated'))}</div><div class="fact-item"><label>${h(t('wilayas'))}</label><a class="text-link" href="#wilaya/${d.wilaya}">${h(provinceName(province(d.wilaya)))}${icon('arrow')}</a></div><div class="fact-item"><label>${h(t('practical'))}</label><p class="tiny">${h(d.sahara?t('summerNote'):t('guidanceNote'))}</p></div><div class="fact-item"><a class="text-link" href="#practical">${h(t('practical'))}${icon('arrow')}</a></div></aside></div>${d.extra?`<div class="photo-pair"><figure>${img(d.photo)}<figcaption>${h(photoLabel(d.photo))} · <button class="hero-credit" style="color:var(--muted)" data-action="photo-credit" data-id="${d.photo}">${h(t('photoCredit'))}</button></figcaption></figure><figure>${img(d.extra)}<figcaption>${h(photoLabel(d.extra))} · <button class="hero-credit" style="color:var(--muted)" data-action="photo-credit" data-id="${d.extra}">${h(t('photoCredit'))}</button></figcaption></figure></div>`:''}${articles.length?`<div class="section-head" style="margin-top:65px"><h2 class="section-title" style="font-size:38px">${h(t('history'))}</h2></div><div class="story-grid">${articles.map(articleCard).join('')}</div>`:''}<div class="data-disclaimer" style="margin-top:45px">${h(t('addressNote'))}<div style="margin-top:12px">${sourceLink('https://www.google.com/maps/search/?api=1&query='+encodeURIComponent('restaurants '+loc(d.name)+' Algérie'),t('searchLocalFood'))}</div></div></div></section>`;}

function historyView(){const articles=allArticles().filter(a=>state.storyFilter==='all'||a.category===state.storyFilter);const featured=state.editorial.articles[2];return `<section class="page-intro"><div class="container"><span class="eyebrow">${h(t('historyEyebrow'))}</span><h1>${h(t('historyTitle'))}</h1><p class="section-desc">${h(t('historyDesc'))}</p><div class="history-tabs">${['all','history','culture','food'].map(k=>`<button class="pill ${state.storyFilter===k?'active':''}" data-action="story-filter" data-filter="${k}">${h(t(k))}</button>`).join('')}</div></div></section><section class="section" style="padding-top:0"><div class="container"><div class="timeline-strip">${state.editorial.articles.slice(0,10).map(a=>`<a href="#article/${a.id}"><strong dir="auto">${a.sortYear<0?Math.abs(a.sortYear)+' BCE':a.sortYear}</strong>${h(loc(ERA_LABELS[a.era]))}</a>`).join('')}</div>${state.storyFilter==='all'&&featured?`<article class="story-feature">${img(articleImage(featured))}<div class="story-feature-content"><span class="eyebrow">${h(t('featured'))} · CHERCHELL</span><h2>${h(loc(featured.title))}</h2><p>${h(cut(loc(featured.body),220))}</p><a href="#article/${featured.id}" class="text-link">${h(t('readStory'))}${icon('arrow')}</a></div></article>`:''}<div class="story-grid">${articles.map(articleCard).join('')}</div></div></section>`;}
function articleView(id){const a=allArticles().find(a=>a.id===id)||state.editorial.culture_profiles.find(a=>a.id===id);if(!a)return notFound();const p=articleImage(a);const text=loc(a.body);const sections=a.sections||[];const words=[text,...sections.map(s=>loc(s.body))].join(' ').split(/\s+/).length;const places=DESTINATIONS.filter(d=>a.places.some(q=>fold(q).includes(fold(loc(d.name).split(' & ')[0]))||d.highlights.some(v=>fold(v).includes(fold(q)))));return `<article class="article"><a class="text-link" href="#history">${h(t('back'))}</a><div class="article-meta"><span class="tag">${h(loc(ERA_LABELS[a.era])||t(a.category))}</span><span>${Math.max(1,Math.ceil(words/200))} ${h(t('reading'))}</span><span>8 ${icon('globe')}</span></div><h1 class="article-heading">${h(loc(a.title))}</h1><div class="button-row" style="margin-bottom:30px"><button class="btn btn-outline btn-small" data-action="favourite" data-key="article:${a.id}">${icon('bookmark')}${h(state.favourites.has('article:'+a.id)?t('saved'):t('save'))}</button></div><figure>${img(p,'article-cover',true)}<figcaption>${h(photoLabel(p))} · ${photoCredit(p)}</figcaption></figure><div class="article-body">${text.split(/\n\n/).map(s=>`<p>${h(s)}</p>`).join('')}${sections.map(s=>`<section class="article-section"><h2>${h(loc(s.heading))}</h2>${loc(s.body).split(/\n\n/).map(v=>`<p>${h(v)}</p>`).join('')}</section>`).join('')}</div><div class="article-sources"><span class="eyebrow">${h(t('extraSources'))}</span>${sourceList(a.sources)}</div>${places.length?`<div class="related-places"><h3>${h(t('storyPlaces'))}</h3><div class="button-row">${places.map(d=>`<a class="pill" href="#destination/${d.id}">${h(loc(d.name))}${icon('arrow')}</a>`).join('')}</div></div>`:''}<div class="button-row" style="margin-top:40px"><a class="btn btn-primary" href="#planner">${h(t('planner'))}${icon('arrow')}</a><a class="btn btn-outline" href="#history">${h(t('allStories'))}</a></div></article>`;}

const cultureImages={'kabylie':'kabylie','aures-chaoui':'timgad','mzab-mozabite':'ghardaia','touareg':'djanet','chaabi-andalou':'casbah','oran-rai':'oran'};
const culturePlaces={'kabylie':'kabylie','aures-chaoui':'timgad','mzab-mozabite':'ghardaia','touareg':'djanet','chaabi-andalou':'alger','oran-rai':'oran'};
function cultureView(){return `<section class="page-intro"><div class="container"><span class="eyebrow">${h(t('tradition'))}</span><h1>${h(t('cultureTitle'))}</h1><p class="section-desc">${h(t('cultureDesc'))}</p></div></section><section class="section" style="padding-top:0"><div class="container"><div class="culture-grid">${state.editorial.culture_profiles.map(c=>`<article class="culture-card">${img(cultureImages[c.id])}<div class="culture-card-content"><h2>${h(loc(c.label))}</h2><p>${h(loc(c.description))}</p><div class="source-links" style="margin-bottom:20px">${sourceLink(c.sources[0]?.url,t('source'))}</div><a class="text-link" href="#destination/${culturePlaces[c.id]}">${h(t('explore'))}${icon('arrow')}</a></div></article>`).join('')}</div><div class="section-head" style="margin-top:90px"><div><span class="eyebrow">${h(t('culture'))} · ${h(t('history'))}</span><h2 class="section-title">${h(t('people'))}</h2></div></div><div class="people-grid">${state.editorial.people.map(p=>`<article class="person-card"><div class="person-monogram">${h(p.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</div><span class="tag">${h(loc(p.sector))}</span><h3 style="margin-top:15px">${h(loc(p.title)||p.name)}</h3><p>${h(loc(p.summary))}</p>${sourceLink(p.sources[0]?.url,t('extraSources'))}</article>`).join('')}</div><div class="section-head" style="margin-top:90px"><h2 class="section-title">${h(t('companies'))}</h2></div><div class="companies-grid">${state.editorial.companies.map(c=>`<article class="company-card"><span class="eyebrow">${h(loc(c.sector))}</span><h3>${h(c.name)}</h3><p>${h(loc(c.summary))}</p>${sourceLink(c.sources[0]?.url,t('goWebsite'))}</article>`).join('')}</div></div></section>`;}
function foodView(){return `<section class="page-intro"><div class="container food-hero"><div><span class="eyebrow">${h(t('food'))}</span><h1 class="section-title">${h(t('foodTitle'))}</h1><p class="section-desc">${h(t('foodDesc'))}</p><a class="text-link" href="#article/cuisine-memoire" style="margin-top:30px">${h(t('readStory'))}${icon('arrow')}</a></div>${img('couscous','',true)}</div></section><section class="section" style="padding-top:20px"><div class="container"><div class="dishes-grid">${DISHES.map((d,i)=>`<article class="dish-card"><div class="dish-number">0${i+1}</div><h3>${h(d.name)}</h3><span class="tag" style="margin-top:15px">${h(d.region)}</span><p>${h(loc(d.desc))}</p><div class="button-row"><a class="text-link" href="#wilaya/${d.wilaya}">${h(t('explore'))}${icon('arrow')}</a>${sourceLink(d.source,t('source'))}</div></article>`).join('')}</div><div class="section-head" style="margin-top:80px"><h2 class="section-title">${h(t('addresses'))}</h2><p class="section-desc">${h(t('addressNote'))}</p></div><div class="restaurant-list">${RESTAURANTS.map(r=>`<article class="restaurant-card"><span class="eyebrow">${h(r.city)}</span><h3>${h(r.name)}</h3><p>${h(t(r.type))} · ${h(t('estimated'))}</p><div class="source-links">${sourceLink(r.url,t('goWebsite'))}${sourceLink('https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(r.name+' '+r.city+' Algérie'),t('onMap'))}</div></article>`).join('')}</div><div class="street-food-box"><div><h3>${h(t('searchLocalFood'))}</h3><p>${h(t('addressNote'))}</p></div><form id="food-search-form"><label for="food-city" class="eyebrow">${h(t('chooseWilaya'))}</label><select id="food-city" class="search-input">${state.wilayas.map(w=>`<option value="${h(w.name_fr)}">${h(provinceName(w))}</option>`).join('')}</select><button class="btn btn-primary" style="margin-top:15px" type="submit">${h(t('searchLocalFood'))}${icon('arrow')}</button></form></div></div></section>`;}

function practicalView(){return `<section class="page-intro"><div class="container"><span class="eyebrow">${h(t('travelNotice'))}</span><h1>${h(t('practical'))}</h1><p class="section-desc">${h(t('guidanceNote'))}</p></div></section><section class="section" style="padding-top:0"><div class="container"><div class="practical-grid">${PRACTICAL.map(p=>`<article class="practical-card">${icon(p.icon)}<h2>${h(loc(p.title))}</h2><p>${h(loc(p.body))}</p>${sourceLink(p.url,t('source'))}</article>`).join('')}</div><div class="button-row" style="margin-top:45px"><a class="btn btn-primary" href="#planner">${h(t('planner'))}${icon('arrow')}</a><a class="btn btn-outline" href="#directory?type=airports">${h(t('airports'))}${icon('plane')}</a></div></div></section>`;}
function sourcesView(){const registry=Object.values(state.editorial.source_registry);return `<section class="page-intro"><div class="container"><span class="eyebrow">BILADI · ${h(t('independent'))}</span><h1>${h(t('sources'))}</h1><p class="section-desc">${h(t('notOfficial'))}</p></div></section><section class="section" style="padding-top:0"><div class="container"><div class="data-disclaimer">${h(t('mapNote'))}<br>${sourceLink('https://www.joradp.dz/FTP/jo-francais/2026/F2026025.pdf','JO25 · 5 April 2026')}${sourceLink('https://www.joradp.dz/FTP/jo-francais/2026/F2026040.pdf','JO40 · 3 June 2026')}<br>${h(t('inventoryNote'))}<div class="source-links">${sourceLink('https://github.com/yasserstudio/geoalgeria','GeoAlgeria · data & source provenance')}${sourceLink('https://github.com/chemsallioua/Algeria69WilayaMap','Chemseddine Allioua · SVG map · MIT')}${sourceLink('https://www.openstreetmap.org/copyright','© OpenStreetMap contributors · ODbL')}<a href="./data/data-license.txt" target="_blank" rel="noopener">Data licences</a><a href="./data/map-license.txt" target="_blank" rel="noopener">Map licence</a><a href="./data/wilaya-boundaries.geojson" download>GeoJSON · 69 wilayas · ODbL</a></div></div><h2 class="section-title" style="font-size:40px;margin-bottom:35px">${h(t('extraSources'))}</h2><div class="source-grid">${registry.map(s=>`<article class="source-card"><h3>${h(s.title)}</h3><p>${h(s.publisher)}</p><div style="margin-top:13px">${sourceLink(s.url,t('source'))}</div></article>`).join('')}</div><h2 class="section-title" style="font-size:40px;margin-block:75px 20px">${h(t('creditIntro'))}</h2><p class="section-desc" style="margin-bottom:35px">${h(loc(L('Photographies réelles, redimensionnées et converties en WebP. Les recadrages de présentation ne modifient pas les scènes. Les auteurs et les licences des images originales sont conservés.','Real photographs, resized and converted to WebP. Presentation crops do not alter the scenes. Original authors and image licences are retained.','صور حقيقية تم تغيير حجمها وتحويلها إلى WebP دون تغيير المشاهد، مع الحفاظ على أسماء المصورين والتراخيص.','Echte Fotos, skaliert und in WebP umgewandelt. Die Szenen bleiben unverändert; Autoren und Lizenzen sind erhalten.','Fotografie reali ridimensionate e convertite in WebP. Scene inalterate, autori e licenze conservati.','Fotos reales redimensionadas y convertidas a WebP. Escenas intactas, autores y licencias conservados.','Fotos reais redimensionadas e convertidas em WebP. Cenas intactas, autores e licenças preservados.','真实照片，经缩放并转换为WebP，场景未改变，保留原作者与许可。')))}</p><div class="photo-credits">${state.photos.map(p=>`<article class="photo-credit-card">${img(p.id)}<div><h3>${h(p.label)}</h3><p>${h(p.photographer)}<br>${sourceLink(p.license_url,p.license)}<br>${sourceLink(p.source_url,t('source'))}</p></div></article>`).join('')}</div><div class="data-disclaimer" style="margin-top:40px">DM Sans · Fraunces · Google Fonts / SIL Open Font License. <a href="./data/font-licenses.txt" target="_blank" rel="noopener">Font licences</a><br>${h(t('localOnly'))}</div></div></section>`;}
function notFound(){return `<section class="page-shell"><h1>${h(t('pageNotFound'))}</h1><a class="btn btn-primary" href="#home" style="margin-top:30px">${h(t('home'))}${icon('arrow')}</a></section>`;}

// Directory records are fetched on demand; all visitor state stays local.
async function loadDirectory(){
 if(state.directoryLoaded)return state.directory;
 if(state.directoryPromise)return state.directoryPromise;
 state.directoryPromise=(async()=>{const files=[['attractions','attractions'],['historic','historic'],['lodging','lodging'],['parks','parks'],['thermal-springs','thermal'],['airports','airports']];const data=await Promise.all(files.map(async([f,kind])=>{const r=await fetch(`./data/${f}.json`);if(!r.ok)throw new Error('Data unavailable');const arr=await r.json();return arr.map(p=>({...p,kind,wilaya_code:String(p.wilaya_code).padStart(2,'0'),key:kind+':'+p.id}));}));state.directory=data.flat();state.directoryLoaded=true;return state.directory;})();
 try{return await state.directoryPromise;}catch(e){state.directoryPromise=null;throw e;}
}
function poiName(p){return lang==='ar'?(p.name_ar||p.name_fr||p.name):(p.name_fr||p.name_en||p.name||p.name_ar);}
function poiMapURL(p){return `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(p.lat+','+p.lng)}`;}
function poiSourceURL(p){if(p.website)return p.website;if(p.source==='osm')return `https://www.openstreetmap.org/?mlat=${p.lat}&mlon=${p.lng}#map=17/${p.lat}/${p.lng}`;if(p.source==='asal')return 'https://geoportail.asal.dz/';return 'https://github.com/yasserstudio/geoalgeria';}
function poiCard(p){return `<article class="poi-card"><span class="tag">${h(t(p.kind))}${p.iata?' · '+h(p.iata):''}</span><h3>${h(poiName(p))}</h3><p class="poi-meta">${h(provinceName(province(p.wilaya_code)))}${p.commune?' · '+h(p.commune):''}</p><div class="poi-actions"><button class="text-link" style="border:0;background:transparent;padding:0" data-action="poi" data-key="${h(p.key)}">${h(t('open'))}${icon('arrow')}</button>${saveButton('poi:'+p.key)}</div></article>`;}
function filteredRecords(code){const query=fold(state.directoryQuery);return state.directory.filter(p=>(!code||p.wilaya_code===code)&&(state.directoryWilaya==='all'||p.wilaya_code===state.directoryWilaya)&&(state.directoryFilter==='all'||p.kind===state.directoryFilter)&&(!query||fold([p.name,p.name_fr,p.name_ar,p.commune,p.iata,provinceName(province(p.wilaya_code))].join(' ')).includes(query)));}
function directoryControls(code){return `<div class="directory-controls"><input id="directory-search" class="search-input" type="search" value="${h(state.directoryQuery)}" placeholder="${h(t('search'))}" aria-label="${h(t('search'))}">${!code?`<select id="directory-wilaya" class="all-directory-wilaya" aria-label="${h(t('chooseWilaya'))}"><option value="all">${h(t('all'))} · 69 ${h(t('wilayas'))}</option>${state.wilayas.map(w=>`<option value="${String(w.code).padStart(2,'0')}" ${state.directoryWilaya===String(w.code).padStart(2,'0')?'selected':''}>${h(provinceName(w))}</option>`).join('')}</select>`:''}</div><div class="filter-row">${['all','attractions','historic','lodging','parks','thermal','airports'].map(k=>`<button class="pill ${state.directoryFilter===k?'active':''}" data-action="directory-filter" data-filter="${k}">${h(t(k))}</button>`).join('')}</div>`;}
function directoryResults(code){if(!state.directoryLoaded)return `<div class="loading-screen" style="min-height:250px"><div class="spinner"></div><p>${h(t('loading'))}</p></div>`;const records=filteredRecords(code);return `<p class="record-count">${records.length} ${h(t('results'))}</p><div class="directory-grid">${records.slice(0,state.directoryLimit).map(poiCard).join('')}</div>${records.length===0?`<p class="data-disclaimer">${h(t('noResults'))}</p>`:''}${records.length>state.directoryLimit?`<div class="load-more"><button class="btn btn-outline" data-action="directory-more">${h(t('more'))}${icon('arrow')}</button></div>`:''}`;}
function wilayaView(code){const w=province(code);if(!w)return notFound();const p=provincePhoto(code),curated=DESTINATIONS.filter(d=>d.wilaya===code);return `<section class="wilaya-banner ${p?'has-image':''}">${p?img(p,'',true):''}<div class="container"><a class="text-link" href="#atlas">${h(t('atlas'))}</a><span class="eyebrow">${h(t('wilayas'))} ${h(code)}${w.created===2026?' · 2026':''}</span><h1 class="wilaya-main-title">${h(provinceName(w))}</h1>${p?`<p class="tiny" style="margin-top:15px">${h(photoLabel(p))} · ${photoCredit(p)}</p>`:''}</div></section><section class="section"><div class="container">${curated.length?`<div class="section-head"><h2 class="section-title" style="font-size:37px">${h(t('featured'))}</h2></div><div class="destination-gallery" style="margin-bottom:55px">${curated.map(d=>destinationCard(d)).join('')}</div>`:''}<div class="section-head"><h2 class="section-title" style="font-size:40px">${h(t('directory'))}</h2><a href="#planner" class="text-link">${h(t('planner'))}${icon('arrow')}</a></div><div class="data-disclaimer">${h(t('inventoryNote'))}</div>${directoryControls(code)}<div id="directory-results">${directoryResults(code)}</div></div></section>`;}
function directoryView(){return `<section class="page-intro"><div class="container"><span class="eyebrow">69 ${h(t('wilayas'))} · 4 348 ${h(t('directory'))}</span><h1>${h(t('searchAll'))}</h1><p class="section-desc">${h(t('atlasDesc'))}</p><div class="data-disclaimer">${h(t('inventoryNote'))}</div>${directoryControls()}<div id="directory-results">${directoryResults()}</div></div></section>`;}

const countryCodes=['DZ','BE','FR','GB','DE','IT','ES','PT','US','CA','CH','NL','TN','MA','JP','CN','AE','SA','IN','BR','AU'];
const displayCountry=c=>{try{return new Intl.DisplayNames([lang==='ar'?'ar-DZ':lang],{type:'region'}).of(c);}catch{return c;}};
const inspirationNames={italy:'IT',greece:'GR',japan:'JP',norway:'NO',jordan:'JO'};
function costFields(p){const names={room:'roomNight',food:'foodDay',activity:'activityDay',sahara:'saharaDay',domestic:'domesticLeg',mobility:'dailyTransport'};return Object.entries(p.costs).map(([k,v])=>`<div class="field"><label for="cost-${k}">${h(k==='roadHour'?loc(L('Chauffeur / groupe / heure de route (DZD)','Driver / group / road hour (DZD)','سائق للمجموعة لكل ساعة (دج)','Fahrer / Gruppe / Fahrtstunde (DZD)','Autista / gruppo / ora su strada (DZD)','Conductor / grupo / hora de carretera (DZD)','Motorista / grupo / hora de estrada (DZD)','司机／组／公路小时（DZD）')):t(names[k]))}</label><input id="cost-${k}" name="cost-${k}" type="number" min="0" max="200000" step="1" value="${v}" required></div>`).join('');}
function plannerForm(p){return `<form id="planner-form" class="planner-form"><section class="form-section"><h2>01 · ${h(t('travelDates'))}</h2><div class="form-grid"><div class="field"><label for="trip-start">${h(t('travelDates'))}</label><input type="date" id="trip-start" name="start" value="${h(p.start)}" min="2026-01-01" max="2035-12-31" required></div><div class="field"><label for="trip-days">${h(t('duration'))} · 3–30 ${h(t('days'))}</label><input id="trip-days" name="days" type="number" min="3" max="30" value="${p.days}" required></div><div class="field"><label for="trip-departure">${h(t('departureCity'))}</label><input id="trip-departure" name="departure" maxlength="80" value="${h(p.departure)}" required></div><div class="field"><label for="trip-nationality">${h(t('nationality'))}</label><select name="nationality" id="trip-nationality">${countryCodes.map(c=>`<option value="${c}" ${p.nationality===c?'selected':''}>${h(displayCountry(c))}</option>`).join('')}<option value="OTHER" ${!countryCodes.includes(p.nationality)?'selected':''}>${h(loc(L('Autre passeport','Other passport','جواز آخر','Anderer Pass','Altro passaporto','Otro pasaporte','Outro passaporte','其他护照')))}</option></select></div><div class="field"><label for="trip-people">${h(t('travellers'))}</label><input id="trip-people" type="number" name="people" min="1" max="12" value="${p.people}" required></div><div class="field"><label for="trip-style">${h(t('comfort'))}</label><select id="trip-style" name="style">${['budget','balanced','premium'].map(k=>`<option value="${k}" ${p.style===k?'selected':''}>${h(t(k))}</option>`).join('')}</select></div></div></section><section class="form-section"><h2>02 · ${h(t('interests'))}</h2><div class="checkbox-chips">${['sea','antiquity','desert','mountain','tradition','food'].map(k=>`<label class="checkbox-chip"><input type="checkbox" name="interests" value="${k}" ${p.interests.includes(k)?'checked':''}>${h(t(k))}</label>`).join('')}</div><label class="eyebrow" style="margin-top:27px">${h(t('inspirations'))}</label><div class="checkbox-chips">${Object.entries(inspirationNames).map(([k,c])=>`<label class="checkbox-chip"><input type="checkbox" name="inspirations" value="${k}" ${p.inspirations.includes(k)?'checked':''}>${h(displayCountry(c))}</label>`).join('')}</div><p class="form-small-note">${h(t('inspirationNote'))}</p></section><section class="form-section"><h2>03 · ${h(t('totalBudget'))}</h2><div class="form-grid"><div class="field"><label for="trip-currency">${h(t('currency'))}</label><select id="trip-currency" name="currency">${CURRENCIES.map(c=>`<option value="${c}" ${p.currency===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label for="trip-rate-mode">${h(t('exchange'))}</label><select id="trip-rate-mode" name="rateMode"><option value="personal" ${p.rateMode==='personal'?'selected':''}>${h(t('personalRate'))}</option><option value="official" ${p.rateMode==='official'?'selected':''} ${p.currency!=='EUR'?'disabled':''}>${h(t('officialRate'))} · EUR</option></select></div><div class="field full"><label for="trip-rate">1 <span data-currency-label>${p.currency}</span> = DZD</label><input id="trip-rate" name="rate" type="number" step="0.0001" min="0.01" max="100000" value="${p.rate}" ${(p.currency==='DZD'||p.rateMode==='official')?'readonly':''} required></div><div class="field"><label for="trip-international">${h(t('flightAllowance'))} (<span data-currency-label>${p.currency}</span>)</label><input id="trip-international" name="international" type="number" min="0" max="100000" value="${p.international}" required></div><div class="field"><label for="trip-visa">${h(t('visaAllowance'))} (<span data-currency-label>${p.currency}</span>)</label><input id="trip-visa" name="visa" type="number" min="0" max="20000" value="${p.visa}" required></div></div><p class="form-small-note">${h(t('rateNote'))}<br>${sourceLink('https://www.bank-of-algeria.dz/taux-de-change-journalier/',t('officialRate')+' · 06/10/2026 · EUR 150.4130')}</p><details class="cost-details"><summary>${h(t('costSettings'))} · DZD</summary><div class="form-grid" id="cost-fields">${costFields(p)}</div></details></section><section class="form-section"><p class="form-small-note">${h(t('estimateNote'))}</p><button type="submit" class="btn btn-primary">${h(t('generate'))}${icon('arrow')}</button></section></form>`;}
function plannerView(params){
 if(params.get('trip')){try{const raw=JSON.parse(params.get('trip'));state.plan=normalizePlan(raw);state.journey=createJourney(state.plan);return journeyView(state.journey);}catch{return notFound();}}
 if(!state.plan){state.plan=normalizePlan(DEFAULT_PLAN);const preset=params.get('preset');if(preset==='antiquity')state.plan=normalizePlan({...DEFAULT_PLAN,days:10,interests:['antiquity','tradition'],inspirations:['italy']});if(preset==='sea')state.plan=normalizePlan({...DEFAULT_PLAN,days:14,interests:['sea','food'],inspirations:['greece']});if(params.get('interest'))state.plan.interests=[params.get('interest')];}
 return `<section class="planner-page section"><div class="container"><div class="planner-header"><div><span class="eyebrow">${h(t('journeyEyebrow'))}</span><h1 class="section-title">${h(t('journeyTitle'))}</h1></div><p class="section-desc">${h(t('journeyDesc'))}</p></div><div class="planner-layout">${plannerForm(state.plan)}<aside class="planner-side">${img('tadrart')}<p class="side-quote">${h(t('heroA'))}<br><em>${h(t('heroB'))}</em></p><p class="aside-note">${h(t('routeExcludes'))}</p><p class="aside-note">${h(t('routeBuffer'))}</p><a class="text-link" href="#practical" style="margin-top:25px">${h(t('practical'))}${icon('arrow')}</a></aside></div></div></section>`;
}
const projectPoint=(lat,lng)=>[(lng+9)*30+35,(38.8-lat)*35+25];
function routeMap(j){let path='',markers=[];let previous=null;let n=0;for(const b of j.blocks){const d=BY_ID[b.id];const [x,y]=projectPoint(d.lat,d.lng);if(previous)path+=`L${x.toFixed(1)},${y.toFixed(1)}`;else path=`M${x.toFixed(1)},${y.toFixed(1)}`;previous=[x,y];if(!markers.some(m=>m.id===b.id))markers.push({id:b.id,x,y,n:++n,name:loc(d.name)});}return `<div class="route-map-wrap"><svg viewBox="0 0 720 710" role="img" aria-label="${h(t('itinerary'))}"><g>${state.mapPaths.map(p=>`<path class="country" d="${h(p.d)}"/>`).join('')}</g><path class="route-line" d="${path}"/>${markers.map(m=>`<g><circle class="route-marker" cx="${m.x}" cy="${m.y}" r="10"/><text class="route-number" x="${m.x}" y="${m.y+3.5}">${m.n}</text><text class="route-label" x="${m.x+15}" y="${m.y+(m.id==='constantine'?17:4)}">${h(m.name)}</text></g>`).join('')}</svg><p class="tiny">${h(loc(L('Schéma des étapes, traits non routiers. © OpenStreetMap · ODbL','Stop overview; lines are not roads. © OpenStreetMap · ODbL','مخطط مراحل وليس طرقاً فعلية. © OpenStreetMap · ODbL','Etappenübersicht; Linien sind keine Straßen. © OpenStreetMap · ODbL','Schema tappe; linee non stradali. © OpenStreetMap · ODbL','Esquema de etapas; líneas no son carreteras. © OpenStreetMap · ODbL','Esquema de etapas; linhas não são estradas. © OpenStreetMap · ODbL','行程示意，连线并非实际道路。© OpenStreetMap · ODbL')))}</p></div>`;}
function flightURL(p,from=p.departure,to='Algiers ALG',start=p.start,end=addDays(p.start,p.days-1)){return 'https://www.google.com/travel/flights?q='+encodeURIComponent(`Flights from ${from} to ${to} on ${start}${end?' returning '+end:''}`);}
const guidedLabel=()=>loc(L('Circuit saharien convenu avec l’agence : guide, accès et étapes à confirmer','Saharan circuit agreed with the agency: confirm guide, access and stops','مسار صحراوي مع الوكالة، مع تأكيد الدليل والوصول والمراحل','Sahara-Tour nach Agenturabsprache: Guide, Zugang und Etappen bestätigen','Circuito Sahara concordato con l’agenzia: conferma guida, accessi e tappe','Circuito sahariano acordado con agencia: confirma guía, acceso y etapas','Circuito saariano acordado com agência: confirme guia, acesso e etapas','与旅行社约定沙漠路线，确认向导、通行与各站安排'));
function dayMarkup(day,j){const d=BY_ID[day.destination];const leg=day.transfer;let slots='';
 if(day.kind==='arrival')slots=`<div class="day-slot"><time>—</time><span>${h(t('arrivalDay'))}</span></div>`;
 else if(day.kind==='departure')slots=`<div class="day-slot"><time>—</time><span>${h(t('departureDay'))}</span></div>`;
 else if(day.kind==='transfer')slots=`<div class="route-transfer">${icon(leg.mode==='flight'?'plane':'car')}<div><strong>${h(loc(BY_ID[leg.from].name))} → ${h(loc(d.name))}</strong><br>${h(t(leg.mode==='flight'?'flight':'road'))} · ${h(t('travelTime'))}: <span dir="ltr">${leg.hourRange||leg.hours} h</span>${leg.via?'<br>'+h(t('flightVia')):''}${leg.mode==='flight'?`<div class="flight-links">${sourceLink(flightURL(j.plan,leg.fromAirport,leg.toAirport,day.date,''),t('searchFlights'))}${sourceLink('https://airalgerie.dz/',t('airline'))}</div>`:`<div class="flight-links">${sourceLink('https://www.google.com/maps/dir/?api=1&origin='+encodeURIComponent(loc(BY_ID[leg.from].name)+' Algeria')+'&destination='+encodeURIComponent(loc(d.name)+' Algeria'),t('onMap'))}</div>`}</div></div><div class="day-slot"><time>—</time><span>${h(t('freeTime'))} · ${h(t('estimated'))}</span></div>`;
 else if(d.sahara)slots=`<div class="day-slot"><time>09:00</time><span>${h(guidedLabel())}</span></div><div class="day-slot"><time>16:00</time><span>${h(t('freeTime'))}</span></div>`;
 else {const hs=d.highlights.filter(s=>!s.includes('Ahellil')&&!s.includes('Sebeïba')&&!s.includes('raï'));const idx=Math.max(0,(day.experienceIndex-1)*2);slots=`<div class="day-slot"><time>09:00</time><span>${h(hs[idx]||t('freeTime'))}</span></div><div class="day-slot"><time>14:30</time><span>${h(hs[idx+1]||t('freeTime'))}</span></div>`;}
 return `<article class="route-day"><div class="day-meta">${h(t('day'))} ${day.number} · ${h(dateLabel(day.date))}</div><h3>${h(loc(d.name))}</h3><div class="day-plan">${slots}</div>${day.kind==='explore'&&day.experienceIndex===1&&d.photo?img(d.photo,'route-photo'):''}<div class="flight-links"><a href="#destination/${d.id}">${h(t('viewDestination'))}</a><a href="#wilaya/${d.wilaya}">${h(t('lodging'))}</a>${sourceLink('https://www.google.com/maps/search/?api=1&query='+encodeURIComponent('restaurants '+loc(d.name)+' Algeria'),t('food'))}</div></article>`;}
function journeyView(j){const p=j.plan;const rows=[...Object.entries(j.budget.local).map(([k,v])=>[k,v/p.rate]),['reserve',j.budget.contingencyDZD/p.rate],...Object.entries(j.budget.foreign)];return `<section class="planner-page section"><div class="container"><span class="eyebrow">${h(t('journeyEyebrow'))}</span><div class="trip-result-header"><div><h1 class="section-title">${h(t('itinerary'))}</h1><p>${p.days} ${h(t('days'))} · ${j.nightTotal} ${h(t('nights'))} · ${p.people} ${h(t('travellers'))}<br>${h(dateLabel(p.start))} → ${h(dateLabel(addDays(p.start,p.days-1)))}</p></div><button class="btn btn-outline" data-action="edit-trip">${h(t('edit'))}${icon('compass')}</button></div><div class="button-row route-actions"><button class="btn btn-primary btn-small" data-action="save-trip">${h(t('save'))}${icon('bookmark')}</button><button class="btn btn-outline btn-small" data-action="print">${h(t('print'))}${icon('download')}</button><button class="btn btn-outline btn-small" data-action="calendar">${h(t('calendar'))}${icon('download')}</button><button class="btn btn-outline btn-small" data-action="share">${h(t('share'))}${icon('arrow')}</button></div>${j.desertExcluded?`<div class="trip-note summer">${h(t('summerNote'))}</div>`:''}<div class="trip-note">${h(t('routeExcludes'))} ${h(t('routeBuffer'))}<br>${h(t('suggestedTimes'))}. ${h(t('guidanceNote'))}</div><div class="route-view"><div class="route-list">${j.days.map(d=>dayMarkup(d,j)).join('')}</div><aside class="route-summary">${routeMap(j)}<div class="budget-card"><h3>${h(t('totalBudget'))}</h3><div class="budget-total">${h(money(j.budget.total,p))}</div><p class="budget-person">${h(money(j.budget.perPerson,p))} ${h(t('perPerson'))} · ${h(t('estimated'))}</p><p class="budget-range">${h(money(j.budget.low,p))} – ${h(money(j.budget.high,p))}</p><p class="budget-foot">${h(t('budgetRange'))}</p><ul class="budget-lines">${rows.map(([k,v])=>`<li><span>${h(t(k))}</span><strong>${h(money(v,p))}</strong></li>`).join('')}</ul><p class="budget-foot">${j.saharaNights?h(t('inclusions'))+'<br>':''}1 ${h(p.currency)} = ${h(p.rate)} DZD · ${h(t(p.rateMode==='official'?'officialRate':'personalRate'))}</p><a class="btn btn-primary" href="${h(flightURL(p))}" target="_blank" rel="noopener">${h(t('searchFlights'))}${icon('plane')}</a><div class="source-links">${sourceLink('https://airalgerie.dz/',t('airline'))}${sourceLink('https://www.mfa.gov.dz/services-for-foreigners/entry-visa-to-algeria',t('checkVisa')+' · '+(p.nationality==='OTHER'?p.nationality:displayCountry(p.nationality)))}</div><p class="budget-foot">${h(t('estimateNote'))}</p><button class="text-link" style="border:0;background:transparent;padding:0" data-action="edit-trip">${h(t('costSettings'))}${icon('arrow')}</button></div></aside></div></div></section>`;}

function notebookView(){const ds=DESTINATIONS.filter(d=>state.favourites.has('destination:'+d.id));const arts=[...allArticles(),...state.editorial.culture_profiles].filter(a=>state.favourites.has('article:'+a.id));const ps=state.directory.filter(p=>state.favourites.has('poi:'+p.key));const trip=state.savedTrip;return `<section class="page-intro"><div class="container"><span class="eyebrow">BILADI · ${h(t('localOnly'))}</span><h1>${h(t('notebook'))}</h1><p class="section-desc">${h(t('emptyNoteDesc'))}</p></div></section><section class="section" style="padding-top:0"><div class="container">${trip?`<article class="saved-trip-card">${img('djanet')}<div><h2>${trip.days} ${h(t('days'))} · ${h(t('itinerary'))}</h2><p>${h(dateLabel(trip.start))} → ${h(dateLabel(addDays(trip.start,trip.days-1)))}</p><div class="button-row" style="margin-top:15px"><a class="btn btn-primary btn-small" href="#planner?trip=${encodeURIComponent(JSON.stringify(trip))}">${h(t('open'))}${icon('arrow')}</a><button class="btn btn-outline btn-small" data-action="remove-trip">${h(t('remove'))}</button></div></div></article>`:''}${!ds.length&&!arts.length&&!ps.length&&!trip?`<div class="empty-state">${icon('bookmark')}<h2>${h(t('emptyNotebook'))}</h2><p>${h(t('emptyNoteDesc'))}</p><a class="btn btn-primary" href="#destinations">${h(t('explore'))}${icon('arrow')}</a></div>`:''}${ds.length?`<section class="notebook-section"><h2>${h(t('discover'))}</h2><div class="notebook-grid">${ds.map(d=>destinationCard(d)).join('')}</div></section>`:''}${arts.length?`<section class="notebook-section"><h2>${h(t('history'))}</h2><div class="story-grid">${arts.map(articleCard).join('')}</div></section>`:''}${ps.length?`<section class="notebook-section"><h2>${h(t('directory'))}</h2><div class="directory-grid">${ps.map(poiCard).join('')}</div></section>`:''}</div></section>`;}

function fold(s){return String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[’']/g,'').replace(/[أإآ]/g,'ا');}
function currentRoute(){const hash=location.hash.slice(1)||'home';const [path,query='']=hash.split('?');const [route,id]=path.split('/');return {route,id,params:new URLSearchParams(query)};}
function updateScrollHeader(){const {route}=currentRoute();document.body.classList.toggle('home-top',route==='home'&&window.scrollY<60);}
async function render(keepScroll=false){
 const version=++renderVersion;const oldScroll=window.scrollY;const {route,id,params}=currentRoute();
 document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';t=translator(lang);renderHeader(route);document.title=`BILADI — ${route==='home'?'El Djazaïr':t({destinations:'discover',atlas:'atlas',wilaya:'atlas',directory:'directory',article:'history',history:'history',planner:'planner',culture:'culture',food:'food',practical:'practical',notebook:'notebook',sources:'sources'}[route]||'home')}`;
 let html;
 if(route==='home')html=homeView();else if(route==='atlas')html=atlasView();else if(route==='destinations')html=destinationsView();else if(route==='destination')html=destinationView(id);else if(route==='history')html=historyView();else if(route==='article')html=articleView(id);else if(route==='culture')html=cultureView();else if(route==='food')html=foodView();else if(route==='practical')html=practicalView();else if(route==='sources')html=sourcesView();else if(route==='planner')html=plannerView(params);else if(route==='notebook')html=notebookView();else if(route==='wilaya')html=wilayaView(id);else if(route==='directory'){if(params.get('type'))state.directoryFilter=params.get('type');html=directoryView();}else html=notFound();
 $('#main').innerHTML=html;bindView();updateScrollHeader();if(keepScroll)window.scrollTo({top:oldScroll,behavior:'instant'});else{window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});}
 if(['wilaya','directory'].includes(route)||route==='notebook'&&Array.from(state.favourites).some(x=>x.startsWith('poi:'))){try{await loadDirectory();if(version!==renderVersion)return;if(route==='notebook'){$('#main').innerHTML=notebookView();}else refreshDirectory();}catch{if(version===renderVersion&&$('#directory-results'))$('#directory-results').innerHTML=`<p class="data-disclaimer">${h(t('dataError'))}</p>`;}}
}

function refreshDirectory(){const {route,id}=currentRoute();if(!$('#directory-results'))return;$('#directory-results').innerHTML=directoryResults(route==='wilaya'?id:undefined);$$('[data-action=directory-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===state.directoryFilter);b.setAttribute('aria-pressed',String(b.dataset.filter===state.directoryFilter));});}
function selectWilaya(code){state.selectedWilaya=code;const s=$('#wilaya-select');if(s)s.value=code;$$('.atlas-map path[data-code]').forEach(p=>{p.classList.toggle('selected',p.dataset.code===code);p.setAttribute('aria-pressed',String(p.dataset.code===code));});const w=province(code),summary=state.summary[code]||{},photo=provincePhoto(code);$('#atlas-selected').innerHTML=`<span class="tag" style="border-color:#ffffff35;margin-top:25px">${h(t('wilayas'))} ${h(code)}</span><h3>${h(provinceName(w))}</h3>${photo?img(photo,'atlas-preview'):''}<div class="wilaya-count"><div><strong>${Object.values(summary).reduce((a,b)=>a+b,0)}</strong><span>${h(t('directory'))}</span></div><div><strong>${summary.lodging||0}</strong><span>${h(t('lodging'))}</span></div></div><a class="btn btn-gold" href="#wilaya/${code}">${h(t('openWilaya'))}${icon('arrow')}</a>`;}
function bindView(){
 $('#wilaya-select')?.addEventListener('change',e=>selectWilaya(e.target.value));
 $$('.atlas-map path[data-code]').forEach(p=>{p.setAttribute('tabindex','0');p.setAttribute('role','button');p.setAttribute('aria-label',provinceName(province(p.dataset.code)));p.classList.toggle('selected',p.dataset.code===state.selectedWilaya);p.setAttribute('aria-pressed',String(p.dataset.code===state.selectedWilaya));p.addEventListener('click',()=>selectWilaya(p.dataset.code));p.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectWilaya(p.dataset.code);}});p.addEventListener('pointermove',e=>{const tip=$('#map-tooltip'),box=$('.atlas-map').getBoundingClientRect();if(!tip)return;tip.textContent=provinceName(province(p.dataset.code));tip.style.display='block';tip.style.left=(e.clientX-box.left)+'px';tip.style.top=(e.clientY-box.top-12)+'px';});p.addEventListener('pointerleave',()=>{if($('#map-tooltip'))$('#map-tooltip').style.display='none';});});
 $('#wilaya-search')?.addEventListener('input',e=>{$('#all-wilayas').innerHTML=wilayaLinks(state.wilayas.filter(w=>fold(w.name_fr+' '+w.name_ar).includes(fold(e.target.value))));});
 $('#directory-search')?.addEventListener('input',e=>{state.directoryQuery=e.target.value;state.directoryLimit=30;refreshDirectory();});
 $('#directory-wilaya')?.addEventListener('change',e=>{state.directoryWilaya=e.target.value;state.directoryLimit=30;refreshDirectory();});
 $('#food-search-form')?.addEventListener('submit',e=>{e.preventDefault();window.open('https://www.google.com/maps/search/?api=1&query='+encodeURIComponent('street food restaurants '+$('#food-city').value+' Algeria'),'_blank','noopener');});
 $('#planner-form')?.addEventListener('submit',e=>{e.preventDefault();state.plan=readPlanForm();location.hash='planner?trip='+encodeURIComponent(JSON.stringify(state.plan));});
 $('#trip-style')?.addEventListener('change',e=>{const p=readPlanForm();p.costs={...COST_PRESETS[e.target.value]};$('#cost-fields').innerHTML=costFields(p);});
 $('#trip-currency')?.addEventListener('change',e=>{const c=e.target.value;$$('[data-currency-label]').forEach(s=>s.textContent=c);const official=$('#trip-rate-mode option[value=official]');official.disabled=c!=='EUR';if(c!=='EUR')$('#trip-rate-mode').value='personal';$('#trip-rate').readOnly=c==='DZD';$('#trip-rate').value=c==='DZD'?'1':c==='EUR'?'278':'';});
 $('#trip-rate-mode')?.addEventListener('change',e=>{$('#trip-rate').readOnly=e.target.value==='official'||$('#trip-currency').value==='DZD';$('#trip-rate').value=e.target.value==='official'?'150.4130':$('#trip-currency').value==='DZD'?'1':$('#trip-currency').value==='EUR'?'278':'';});
}
function readPlanForm(){const f=new FormData($('#planner-form'));const costs={};Object.keys(COST_PRESETS.balanced).forEach(k=>costs[k]=f.get('cost-'+k));return normalizePlan({start:f.get('start'),days:f.get('days'),departure:f.get('departure'),nationality:f.get('nationality'),people:f.get('people'),interests:f.getAll('interests'),inspirations:f.getAll('inspirations'),style:f.get('style'),currency:f.get('currency'),rateMode:f.get('rateMode'),rate:f.get('rate'),international:f.get('international'),visa:f.get('visa'),costs});}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast')?.classList.remove('show'),2800);}
function openPhoto(id){const p=state.photos.find(x=>x.id===id);if(!p)return;$('#detail-dialog').innerHTML=`<button class="icon-btn dialog-close" data-action="close-detail" aria-label="${h(t('close'))}">${icon('close')}</button>${img(p.id,'',true)}<div class="detail-dialog-content"><span class="eyebrow">${h(t('photoCredit'))}</span><h2>${h(p.label)}</h2><p>${h(loc(p.alt))}</p><p>${h(p.photographer)} · ${h(p.license)}</p><div class="source-links">${sourceLink(p.source_url,t('source'))}${sourceLink(p.license_url,p.license)}</div></div>`;$('#detail-dialog').showModal();}
function openPoi(key){const p=state.directory.find(p=>p.key===key);if(!p)return;$('#detail-dialog').innerHTML=`<button class="icon-btn dialog-close" data-action="close-detail" aria-label="${h(t('close'))}">${icon('close')}</button><div class="detail-dialog-content"><span class="eyebrow">${h(t(p.kind))} · ${h(provinceName(province(p.wilaya_code)))}</span><h2>${h(poiName(p))}</h2><p>${h(p.address||p.commune||'')}<br>${p.iata?'IATA '+h(p.iata)+' · ICAO '+h(p.icao)+'<br>':''}<span dir="ltr">${Number(p.lat).toFixed(4)}, ${Number(p.lng).toFixed(4)}</span><br>${h(t('source'))}: ${h(p.source)} · ${h(p.geo_precision||'')}</p><p style="margin-top:20px">${h(t('inventoryNote'))}</p><div class="source-links">${sourceLink(poiMapURL(p),t('onMap'))}${sourceLink(poiSourceURL(p),t('source'))}${p.phone?`<span>${h(p.phone)}</span>`:''}</div><button class="btn btn-primary" style="margin-top:25px" data-action="favourite" data-key="poi:${h(p.key)}">${h(state.favourites.has('poi:'+p.key)?t('saved'):t('save'))}${icon('bookmark')}</button></div>`;$('#detail-dialog').showModal();}
async function openSearch(){state.searchQuery='';$('#search-dialog').innerHTML=`<div class="search-dialog-header">${icon('search')}<input id="global-search" type="search" placeholder="${h(t('search'))}" aria-label="${h(t('search'))}" autocomplete="off"><button class="icon-btn" data-action="close-search" aria-label="${h(t('close'))}">${icon('close')}</button></div><div class="search-results" id="search-results"></div>`;$('#search-dialog').showModal();$('#global-search').focus();renderSearch();$('#global-search').addEventListener('input',e=>{state.searchQuery=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(renderSearch,100);});try{await loadDirectory();if($('#search-dialog').open)renderSearch();}catch{}}
function renderSearch(){if(!$('#search-results'))return;const q=fold(state.searchQuery);const items=[];
 for(const d of DESTINATIONS){if(!q||fold(Object.values(d.name).join(' ')+' '+d.highlights.join(' ')).includes(q))items.push({name:loc(d.name),meta:t(d.theme),url:'#destination/'+d.id,photo:d.photo});}
 if(q){for(const w of state.wilayas)if(fold(w.name_ar+' '+w.name_fr).includes(q))items.push({name:provinceName(w),meta:t('wilayas')+' '+String(w.code).padStart(2,'0'),url:'#wilaya/'+String(w.code).padStart(2,'0')});for(const a of allArticles())if(fold(Object.values(a.title).join(' ')+' '+loc(a.body)+' '+(a.sections||[]).map(s=>loc(s.heading)+' '+loc(s.body)).join(' ')).includes(q))items.push({name:loc(a.title),meta:t('history'),url:'#article/'+a.id,photo:articleImage(a)});for(const p of state.directory){if(fold([p.name,p.name_fr,p.name_ar,p.iata].join(' ')).includes(q))items.push({name:poiName(p),meta:t(p.kind)+' · '+provinceName(province(p.wilaya_code)),poi:p.key});if(items.length>=70)break;}}
 $('#search-results').innerHTML=items.length?items.slice(0,40).map(i=>`<a class="search-result" ${i.poi?`href="#directory" data-action="search-poi" data-key="${h(i.poi)}"`:`href="${h(i.url)}" data-action="search-navigate"`}>${i.photo?img(i.photo):`<span class="search-result-icon">${icon('pin')}</span>`}<span><h3>${h(i.name)}</h3><p>${h(i.meta)}</p></span>${icon('arrow')}</a>`).join(''):`<p class="data-disclaimer">${h(t('noResults'))}</p>`;
}
function toggleFavourite(key){if(state.favourites.has(key))state.favourites.delete(key);else state.favourites.add(key);if(!writeStore('biladi-favourites',[...state.favourites]))toast(t('dataError'));else toast(state.favourites.has(key)?t('saved'):t('remove'));$$(`[data-key="${CSS.escape(key)}"][data-action=favourite]`).forEach(b=>{const active=state.favourites.has(key);b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));b.setAttribute('aria-label',active?t('saved'):t('save'));if(!b.classList.contains('icon-btn'))b.innerHTML=icon('bookmark')+h(active?t('saved'):t('save'));});if(currentRoute().route==='notebook')render(true);}
function downloadText(filename,text,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('click',async e=>{
 const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;
 if(action==='skip-main'){e.preventDefault();$('#main').focus({preventScroll:true});$('#main').scrollIntoView({behavior:'instant'});}
 if(action==='menu'){const m=$('#mobile-menu');m.classList.toggle('open');b.setAttribute('aria-expanded',String(m.classList.contains('open')));}
 if(action==='search')openSearch();if(action==='close-search'||action==='search-navigate')$('#search-dialog').close();if(action==='close-detail')$('#detail-dialog').close();
 if(action==='search-poi'){e.preventDefault();$('#search-dialog').close();openPoi(b.dataset.key);}
 if(action==='photo-credit')openPhoto(b.dataset.id);if(action==='poi')openPoi(b.dataset.key);if(action==='favourite')toggleFavourite(b.dataset.key);
 if(action==='hero'){state.hero=Number(b.dataset.index);const old=$('.hero');old.outerHTML=heroMarkup();}
 if(action==='home-filter'){state.destFilter=b.dataset.filter;const ds=state.destFilter==='all'?['bejaia','djanet','tipasa','constantine','ghardaia'].map(k=>BY_ID[k]):DESTINATIONS.filter(d=>d.theme===state.destFilter).slice(0,5);$('.discover-grid').innerHTML=ds.map((d,i)=>destinationCard(d,i===0)).join('');$$('[data-action=home-filter]').forEach(x=>{x.classList.toggle('active',x.dataset.filter===state.destFilter);x.setAttribute('aria-pressed',String(x.dataset.filter===state.destFilter));});}
 if(action==='destination-filter'){state.destFilter=b.dataset.filter;render(true);}if(action==='story-filter'){state.storyFilter=b.dataset.filter;render(true);}
 if(action==='directory-filter'){state.directoryFilter=b.dataset.filter;state.directoryLimit=30;refreshDirectory();}if(action==='directory-more'){state.directoryLimit+=30;refreshDirectory();}
 if(action==='edit-trip'){state.plan=state.journey.plan;state.journey=null;location.hash='planner';}
 if(action==='save-trip'){state.savedTrip=state.journey.plan;toast(writeStore('biladi-trip',state.savedTrip)?t('savedTrip'):t('dataError'));}
 if(action==='remove-trip'){state.savedTrip=null;writeStore('biladi-trip',null);render(true);}
 if(action==='print')window.print();
 if(action==='calendar'&&state.journey)downloadText('BILADI-itineraire.ics',calendarFile(state.journey,d=>t('day')+' '+d.number+' · '+loc(BY_ID[d.destination].name)),'text/calendar;charset=utf-8');
 if(action==='share'){try{await navigator.clipboard.writeText(location.href);toast(t('copied'));}catch{const input=document.createElement('input');input.value=location.href;document.body.append(input);input.select();document.execCommand('copy');input.remove();toast(t('copied'));}}
 if(action==='scroll-discover')$('#home-discover')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});
});
document.addEventListener('change',e=>{if(e.target.matches('.lang-picker')){lang=e.target.value;writeStore('biladi-lang',lang);render(true);}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch();}});
for(const id of ['search-dialog','detail-dialog'])$('#'+id).addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.currentTarget.close();}});
window.addEventListener('scroll',updateScrollHeader,{passive:true});
window.addEventListener('hashchange',()=>{const {route,params}=currentRoute();if(route==='planner'&&(params.has('preset')||params.has('interest')))state.plan=null;state.directoryLimit=30;state.directoryQuery='';state.directoryFilter='all';state.directoryWilaya='all';render();});
async function boot(){
 $('#main').innerHTML=`<div class="loading-screen"><span class="brand-name">BILADI</span><div class="spinner"></div><p>${h(t('scroll'))}</p></div>`;
 try{const urls=['wilayas.json','photos.json','editorial.json','catalog-summary.json','map-paths.json'];const [wilayas,photos,editorial,summary,mapPaths,svg]=await Promise.all([...urls.map(async f=>{const r=await fetch('./data/'+f);if(!r.ok)throw new Error(f);return r.json();}),fetch('./assets/algeria-69.svg').then(r=>{if(!r.ok)throw new Error('map');return r.text();})]);Object.assign(state,{wilayas,photos,editorial,summary,mapPaths,svg});if(state.savedTrip)state.savedTrip=normalizePlan(state.savedTrip);await render();}
 catch{$('#main').innerHTML=`<section class="page-shell"><h1>BILADI — El Djazaïr</h1><p style="margin-top:25px">${h(t('dataError'))}</p><button class="btn btn-primary" style="margin-top:25px" data-action="reload">${h(t('reset'))}</button></section>`;document.addEventListener('click',e=>{if(e.target.closest('[data-action=reload]'))location.reload();});}
}
export const bootPromise=boot();
